final class RecordingLedger implements Ledger {
    private final Map<String, Long> balances = new HashMap<>();
    private final List<Operation> journal = new ArrayList<>();

    @Override public void deposit(String id, long amount) {
        balances.merge(id, amount, Long::sum);              // working behaviour
        journal.add(new Operation("deposit", id, amount));  // recorded interaction
    }

    List<Operation> journal() { return List.copyOf(journal); } // test-only accessor
}
